        .declarations
        .iter()
        .filter(|declaration| declaration.category.is_donation_support())
        .take(RECENT_SUPPORT)
        .cloned()
        .collect();
    MemberDetails {
        member: history.member,
        declarations: history.declarations,
        summary,
        recent_support,
    }
}

